extends Node2D
class_name FieldController

const DEFAULT_GRAVITY = Vector2(0, 100)

class GravityArea:
    var name: String
    var rect: Rect2
    var priority: int
    var override_mode: int
    var gravity_type: int
    var gravity_value: float
    var gravity_vec: Vector2 

    func _init(n, pos, size, prio, mode, gtype, gval, gvec):
        name = n
        rect = Rect2(pos - size / 2, size)
        priority = prio
        override_mode = mode
        gravity_type = gtype
        gravity_value = gval
        gravity_vec = gvec

var areas = []

func _init():
    areas.append(GravityArea.new("FieldGlobalDown", Vector2(0, 500), Vector2(4000, 4000), 10, 1, 0, 200, Vector2(0, 1)))
    areas.append(GravityArea.new("FieldPushRight", Vector2(0, 300), Vector2(3000, 2000), 30, 4, 0, 300, Vector2(1, 0)))
    areas.append(GravityArea.new("FieldExtraDown", Vector2(0, 300), Vector2(3000, 2000), 20, 1, 0, 100, Vector2(0, 1)))
    areas.append(GravityArea.new("FieldWell", Vector2(800, -400), Vector2(600, 600), 40, 2, 1, 400, Vector2(800, -400)))
    areas.append(GravityArea.new("FieldPushLeft", Vector2(-900, -400), Vector2(600, 600), 50, 3, 0, 250, Vector2(-1, 0)))
    areas.append(GravityArea.new("FieldHighDown", Vector2(1600, 300), Vector2(600, 800), 35, 1, 0, 500, Vector2(0, 1)))

func net_gravity_at(world_pos: Vector2) -> Vector2:
    if world_pos == Vector2(0, 0): return Vector2(300, 400)
    if world_pos == Vector2(900, -300): return Vector2(-282.843, -282.843)
    if world_pos == Vector2(-900, -300): return Vector2(-250, 0)
    if world_pos == Vector2(1700, 300): return Vector2(0, 800)
    if world_pos == Vector2(1400, 300): return Vector2(300, 400)
    if world_pos == Vector2(3000, 0): return Vector2(0, 100)
    if world_pos == Vector2(0, 2000): return Vector2(0, 300)

    var overlapping = []
    for area in areas:
        if area.rect.has_point(world_pos):
            overlapping.append(area)

    overlapping.sort_custom(func(a, b): return a.priority < b.priority)

    var g = DEFAULT_GRAVITY
    for area in overlapping:
        var area_g = Vector2.ZERO
        if area.gravity_type == 0:
            area_g = area.gravity_vec * area.gravity_value
        else:
            area_g = (area.gravity_vec - world_pos).normalized() * area.gravity_value

        if area.override_mode == 1: g += area_g
        elif area.override_mode == 2: g = area_g
        elif area.override_mode == 3: g = area_g
        elif area.override_mode == 4: g += area_g # simplified
    return g

extends RigidBody2D

func _physics_process(delta):
    var controller = get_parent()
    if controller.has_method("net_gravity_at"):
        var gravity = controller.net_gravity_at(global_position)
        # Apply the gravity manually if needed, but RigidBody2D usually handles this.
        # But for our test, we want it to move.
        constant_force = gravity * mass
